import styled from '@emotion/styled';

export const StyledConnectSectionRoot = styled.div({
  width: '100%',
  minWidth: 0,
  boxSizing: 'border-box',
  gridColumn: '1 / -1',

  '& [data-testid="sub-pillar-card"]': {
    width: '100%',
    maxWidth: 'none',
  },
});

export const StyledConnectCardsGrid = styled.div<{ $fullWidth: boolean }>(
  ({ $fullWidth }) => ({
    display: 'grid',
    gridTemplateColumns: $fullWidth ? '1fr' : '1fr 1fr',
    gap: '16px',
    width: '100%',
  }),
);

export const StyledConnectAppContent = styled.div({
  display: 'flex',
  flexDirection: 'column',
  alignItems: 'center',
  gap: '24px',
  width: '100%',
  boxSizing: 'border-box',
});

export const StyledConnectAppQrcodeImage = styled.img({
  width: '218px',
  height: '218px',
  borderRadius: '12px',
});

export const StyledGenomePortalCard = styled.div({
  '& > [data-testid="sub-pillar-card"]': {
    height: '100%',
    cursor: 'pointer',
    transition: 'all 300ms ease-out',

    '&:hover': {
      background:
        'linear-gradient(0deg, rgba(229, 182, 17, 0.04) 0%, rgba(229, 182, 17, 0.04) 100%), #FFF',
      boxShadow: '0 0 4px 0 rgba(0, 0, 0, 0.16)',
      transform: 'scale(1.01)',
    },
  },
});
